sp_widget.client_script:
api.controller = function($window) {

  /* =========================================================
     GATENOW · PROGRAM DETAIL · Client script

     One job: hand off to the intake page carrying the program
     sys_id, so the form on the other side knows which program
     is being applied to.

     $window is injected rather than reaching for the global,
     which keeps the widget testable and out of the way of the
     coding standards check.
     ========================================================= */

  var c = this;

  c.startApplication = function(sysId) {

    if (!sysId || !c.data.canApply) return;

    var page  = c.data.intakePage || 'applicant_intake';
    var param = c.data.intakeParam || 'sys_id';

    $window.location.href = '?id=' + page + '&' + param + '=' + encodeURIComponent(sysId);
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · PROGRAM DETAIL
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Same tokens as the programs listing, deliberately. A detail
   page that restyles itself makes the visitor wonder whether
   they left the site.

   COLOUR
   One accent, the logo blue, meaning you can act on this.
   Neutrals are all the same navy at different opacities. Teal
   is opening soon, amber is closing inside a week, neutral is
   closed. Four states, four meanings, nothing decorative.

   TYPE
     display   44  700  -0.033em   program name
     section   19  600  -0.018em   section headings
     lead    18.5  400              synopsis
     body    16.5  400              long copy, 68ch measure
     data      15  600  tabular     dates and amounts
     label     11  600   0.14em     uppercase small caps
   ========================================================= */

/* ---------- typeface ----------
   Shared with the other widgets. Keep one copy in a Style Sheet
   record attached to the theme if several appear on a portal.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$d-navy:    #0a2540;
$d-ink-2:   rgba(10, 37, 64, 0.72);
$d-ink-3:   rgba(10, 37, 64, 0.54);
$d-ink-4:   rgba(10, 37, 64, 0.38);
$d-line:    rgba(10, 37, 64, 0.10);
$d-line-2:  rgba(10, 37, 64, 0.06);
$d-tint:    rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$d-blue:    #1560e0;
$d-blue-dk: #0f4cbb;
$d-blue-1:  rgba(21, 96, 224, 0.08);
$d-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- state ---------- */
$d-soon:    #0d7d8c;
$d-warn:    #a4741f;
$d-warn-1:  rgba(164, 116, 31, 0.10);
$d-warn-2:  rgba(164, 116, 31, 0.26);

$d-white:   #ffffff;
$d-ease:    cubic-bezier(0.45, 0.05, 0.25, 1);

$d-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gnpd {
  position: relative;
  width: 100%;
  min-height: 100vh;
  font-family: $d-font;
  color: $d-navy;
  background: $d-white;
  -webkit-font-smoothing: antialiased;
}

.gnpd *,
.gnpd *::before,
.gnpd *::after { box-sizing: border-box; }


/* =========================================================
   HEADER
   ========================================================= */

.gnpd-head {
  position: relative;
  padding: 34px 24px 54px;
  overflow: hidden;
  border-bottom: 1px solid $d-line;
  background: linear-gradient(180deg, #f2f6fc 0%, #f8fafd 66%, #ffffff 100%);
}

.gnpd-head__glow {
  position: absolute;
  top: -280px;
  left: 50%;
  width: 1000px;
  height: 620px;
  margin-left: -500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(21, 96, 224, 0.07) 0%, rgba(21, 96, 224, 0) 68%);
  pointer-events: none;
}

.gnpd-head__inner {
  position: relative;
  z-index: 2;
  max-width: 1180px;
  margin: 0 auto;
}

.gnpd-back {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 30px;
  font-size: 14px;
  font-weight: 500;
  color: $d-ink-3;
  text-decoration: none;
  transition: color 0.4s $d-ease;
}

.gnpd-back:hover,
.gnpd-back:focus {
  color: $d-blue-dk;
  text-decoration: none;
}

.gnpd-back__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid $d-line;
  font-size: 12px;
  transition: transform 0.4s $d-ease, border-color 0.4s $d-ease;
}

.gnpd-back:hover .gnpd-back__arrow {
  transform: translateX(-3px);
  border-color: $d-blue-2;
}

.gnpd-head__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 16px;
}

.gnpd-state {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.gnpd-state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gnpd-state--open   { color: $d-blue-dk; }
.gnpd-state--soon   { color: $d-soon; }
.gnpd-state--closed { color: $d-ink-4; }

.gnpd-state--open .gnpd-state__dot { background: $d-blue; }
.gnpd-state--soon .gnpd-state__dot { background: $d-soon; }
.gnpd-state--closed .gnpd-state__dot {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.28);
}

/* category and reference are the same kind of information, so
   they share one style */
.gnpd-head__tags {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $d-ink-4;
}

.gnpd-head__sep { color: rgba(10, 37, 64, 0.22); }

/* display role */
.gnpd .gnpd-title {
  margin: 0;
  max-width: 20ch;
  font-size: 44px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.033em;
  color: $d-navy;
}

@supports (font-size: clamp(28px, 3.6vw, 44px)) {
  .gnpd .gnpd-title { font-size: clamp(28px, 3.6vw, 44px); }
}

/* lead role */
.gnpd .gnpd-lead {
  max-width: 60ch;
  margin: 18px 0 0;
  padding: 0;
  font-size: 18.5px;
  font-weight: 400;
  line-height: 1.62;
  color: $d-ink-2;
  white-space: pre-line;
}

.gnpd .gnpd-countdown {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 22px 0 0;
  padding: 7px 14px 7px 12px;
  border: 1px solid $d-line;
  border-radius: 999px;
  background: $d-white;
  font-size: 13.5px;
  font-weight: 600;
  color: $d-ink-2;
}

/* the only warm colour on the page, and only inside the last
   seven days */
.gnpd .gnpd-countdown.is-urgent {
  border-color: $d-warn-2;
  background: $d-warn-1;
  color: $d-warn;
}

.gnpd-countdown__pulse {
  position: relative;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $d-blue;
  flex-shrink: 0;
}

.gnpd-countdown.is-urgent .gnpd-countdown__pulse { background: $d-warn; }


/* =========================================================
   BODY
   ========================================================= */

.gnpd-body { padding: 54px 24px 104px; }

.gnpd-body__inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 372px;
  gap: 64px;
  align-items: start;
  max-width: 1180px;
  margin: 0 auto;
}

.gnpd-main { min-width: 0; }


/* ---------- announcement ---------- */

.gnpd-notice {
  padding: 20px 24px 22px;
  margin-bottom: 42px;
  border: 1px solid $d-blue-2;
  border-radius: 14px;
  background: $d-blue-1;
}

.gnpd-notice__label {
  display: block;
  margin-bottom: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $d-blue-dk;
}

.gnpd .gnpd-notice__text {
  margin: 0;
  padding: 0;
  max-width: 68ch;
  font-size: 15.5px;
  line-height: 1.68;
  color: $d-ink-2;
  white-space: pre-line;
}


/* ---------- sections ---------- */

.gnpd-sec {
  padding-bottom: 34px;
  margin-bottom: 34px;
  border-bottom: 1px solid $d-line-2;
}

.gnpd-sec:last-child {
  padding-bottom: 0;
  margin-bottom: 0;
  border-bottom: 0;
}

/* section role */
.gnpd .gnpd-sec__title {
  margin: 0 0 14px;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.018em;
  color: $d-navy;
}

/* body role, held to a measure and keeping the line breaks the
   author typed into the field */
.gnpd .gnpd-sec__text {
  margin: 0;
  padding: 0;
  max-width: 68ch;
  font-size: 16.5px;
  font-weight: 400;
  line-height: 1.74;
  color: $d-ink-2;
  white-space: pre-line;
}


/* =========================================================
   RAIL
   ========================================================= */

.gnpd-rail {
  position: sticky;
  top: 24px;
  min-width: 0;
}

.gnpd-panel {
  border: 1px solid $d-line;
  border-radius: 18px;
  background: $d-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.04),
              0 18px 44px rgba(10, 37, 64, 0.06);
}

.gnpd-block {
  padding: 22px 24px 24px;
  border-bottom: 1px solid $d-line-2;
}

.gnpd-block__label {
  margin: 0 0 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $d-ink-4;
}

/* the one number on the page big enough to read from across the
   desk, because it is the one that decides whether to apply */
.gnpd .gnpd-figure {
  margin: 0;
  padding: 0;
  font-size: 27px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $d-navy;
}

.gnpd .gnpd-figure__note {
  margin: 5px 0 0;
  padding: 0;
  font-size: 12.5px;
  color: $d-ink-4;
}

.gnpd .gnpd-rows {
  display: grid;
  gap: 11px;
  margin: 18px 0 0;
  padding: 0;
}

.gnpd-block__label + .gnpd-rows { margin-top: 0; }

.gnpd-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}

.gnpd .gnpd-row dt {
  margin: 0;
  font-size: 13.5px;
  font-weight: 400;
  color: $d-ink-3;
}

/* data role */
.gnpd .gnpd-row dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: $d-navy;
}


/* ---------- dates ---------- */

.gnpd .gnpd-time {
  position: relative;
  margin: 0;
  padding: 0 0 0 22px;
  list-style: none;
}

/* the thread behind the nodes */
.gnpd .gnpd-time::before {
  content: "";
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 4px;
  width: 2px;
  border-radius: 2px;
  background: $d-line;
  transform-origin: center top;
}

.gnpd-time__step {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 15px;
}

.gnpd-time__step:last-child { padding-bottom: 0; }

.gnpd-time__node {
  position: absolute;
  top: 6px;
  left: -22px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: $d-white;
  box-shadow: inset 0 0 0 2px rgba(10, 37, 64, 0.24);
}

/* the closing date is the one that costs you if you miss it */
.gnpd-time__step.is-key .gnpd-time__node {
  background: $d-blue;
  box-shadow: 0 0 0 3px $d-blue-1;
}

.gnpd-time__label {
  font-size: 13.5px;
  color: $d-ink-3;
}

.gnpd-time__step.is-key .gnpd-time__label {
  font-weight: 600;
  color: $d-navy;
}

.gnpd-time__date {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: $d-navy;
}


/* ---------- action ---------- */

.gnpd-act {
  padding: 22px 24px 24px;
  background: $d-tint;
}

.gnpd-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  height: 54px;
  padding: 0 20px;
  border: 0;
  border-radius: 12px;
  overflow: hidden;
  background: $d-blue;
  color: $d-white;
  font-family: inherit;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
  cursor: pointer;
  box-shadow: 0 12px 26px rgba(21, 96, 224, 0.26);
  transition: transform 0.5s $d-ease,
              background 0.5s $d-ease,
              box-shadow 0.5s $d-ease;
}

.gnpd-btn:hover {
  transform: translateY(-2px);
  background: $d-blue-dk;
  box-shadow: 0 18px 36px rgba(21, 96, 224, 0.32);
}

.gnpd-btn:focus-visible {
  outline: 2px solid $d-blue;
  outline-offset: 3px;
}

.gnpd-btn__label { position: relative; z-index: 2; }

.gnpd-btn__arrow {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  font-size: 12px;
  transition: transform 0.5s $d-ease, background 0.5s $d-ease;
}

.gnpd-btn:hover .gnpd-btn__arrow {
  transform: translateX(4px);
  background: rgba(255, 255, 255, 0.28);
}

/* one pass of light across the face on hover */
.gnpd-btn__shine {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -60%;
  z-index: 1;
  width: 45%;
  transform: skewX(-18deg);
  background: linear-gradient(90deg,
              rgba(255, 255, 255, 0) 0%,
              rgba(255, 255, 255, 0.2) 50%,
              rgba(255, 255, 255, 0) 100%);
  transition: left 0.75s $d-ease;
  pointer-events: none;
}

.gnpd-btn:hover .gnpd-btn__shine { left: 115%; }

/* Closed and not yet open are drawn as a statement rather than
   a dead button. A greyed out control invites clicking; a plain
   panel does not. */
.gnpd-btn--off {
  background: transparent;
  border: 1px dashed rgba(10, 37, 64, 0.22);
  color: $d-ink-3;
  cursor: default;
  box-shadow: none;
  font-weight: 500;
}

.gnpd-btn--off:hover {
  transform: none;
  background: transparent;
  box-shadow: none;
}

.gnpd .gnpd-act__note {
  margin: 13px 0 0;
  padding: 0;
  font-size: 13px;
  line-height: 1.58;
  color: $d-ink-3;
}

.gnpd .gnpd-act__note strong {
  font-weight: 600;
  color: $d-navy;
}


/* =========================================================
   NOT FOUND
   ========================================================= */

.gnpd--missing {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 120px 24px;
}

.gnpd-missing {
  max-width: 44ch;
  text-align: center;
}

.gnpd .gnpd-missing__title {
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.024em;
  color: $d-navy;
}

.gnpd .gnpd-missing__text {
  margin: 12px 0 0;
  padding: 0;
  font-size: 16px;
  line-height: 1.68;
  color: $d-ink-2;
}

.gnpd-missing__link {
  display: inline-flex;
  align-items: center;
  height: 46px;
  margin-top: 24px;
  padding: 0 22px;
  border: 1px solid $d-line;
  border-radius: 10px;
  color: $d-navy;
  font-size: 14.5px;
  font-weight: 600;
  text-decoration: none;
  transition: border-color 0.4s $d-ease, color 0.4s $d-ease;
}

.gnpd-missing__link:hover,
.gnpd-missing__link:focus {
  border-color: $d-blue-2;
  color: $d-blue-dk;
  text-decoration: none;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gnpdRise {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gnpdSlide {
    from { opacity: 0; transform: translateX(18px); }
    to   { opacity: 1; transform: translateX(0); }
  }

  @keyframes gnpdDrop {
    from { transform: scaleY(0); }
    to   { transform: scaleY(1); }
  }

  @keyframes gnpdPulse {
    0%   { box-shadow: 0 0 0 0 rgba(21, 96, 224, 0.4); }
    70%  { box-shadow: 0 0 0 7px rgba(21, 96, 224, 0); }
    100% { box-shadow: 0 0 0 0 rgba(21, 96, 224, 0); }
  }

  .gnpd-back,
  .gnpd-head__meta,
  .gnpd .gnpd-title,
  .gnpd .gnpd-lead,
  .gnpd .gnpd-countdown {
    animation: gnpdRise 0.7s $d-ease backwards;
  }

  .gnpd-head__meta        { animation-delay: 0.05s; }
  .gnpd .gnpd-title       { animation-delay: 0.11s; }
  .gnpd .gnpd-lead        { animation-delay: 0.18s; }
  .gnpd .gnpd-countdown   { animation-delay: 0.25s; }

  .gnpd-notice { animation: gnpdRise 0.66s $d-ease 0.3s backwards; }

  .gnpd-sec { animation: gnpdRise 0.66s $d-ease backwards; }

  .gnpd-sec--1 { animation-delay: 0.34s; }
  .gnpd-sec--2 { animation-delay: 0.40s; }
  .gnpd-sec--3 { animation-delay: 0.46s; }
  .gnpd-sec--4 { animation-delay: 0.52s; }

  /* the rail arrives from its own side */
  .gnpd-panel { animation: gnpdSlide 0.72s $d-ease 0.3s backwards; }

  .gnpd .gnpd-time::before {
    animation: gnpdDrop 0.8s $d-ease 0.55s backwards;
  }

  /* each date lands as the thread reaches it */
  .gnpd-time__step { animation: gnpdRise 0.5s $d-ease backwards; }

  .gnpd-time__step--1 { animation-delay: 0.62s; }
  .gnpd-time__step--2 { animation-delay: 0.70s; }
  .gnpd-time__step--3 { animation-delay: 0.78s; }
  .gnpd-time__step--4 { animation-delay: 0.86s; }

  /* one slow ring on the live countdown, and nowhere else */
  .gnpd-countdown__pulse {
    animation: gnpdPulse 2.8s $d-ease 1.2s infinite;
  }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1080px) {

  .gnpd-head { padding: 28px 20px 46px; }

  .gnpd-body { padding: 40px 20px 84px; }

  .gnpd-body__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 44px;
  }

  /* the rail moves above the reading column, since the action
     matters more than the terms on a narrow screen */
  .gnpd-rail {
    position: static;
    order: -1;
  }

  .gnpd-main { order: 1; }

  .gnpd .gnpd-title { max-width: none; }
}

@media (max-width: 620px) {

  .gnpd-head { padding: 22px 16px 38px; }

  .gnpd-back { margin-bottom: 22px; }

  .gnpd-body { padding: 32px 16px 70px; }

  .gnpd .gnpd-lead { font-size: 17px; }

  .gnpd-notice {
    padding: 17px 18px 19px;
    margin-bottom: 32px;
  }

  .gnpd-sec {
    padding-bottom: 26px;
    margin-bottom: 26px;
  }

  .gnpd .gnpd-sec__title { font-size: 17.5px; }
  .gnpd .gnpd-sec__text { font-size: 15.5px; }

  .gnpd-block { padding: 19px 18px 20px; }
  .gnpd-act { padding: 19px 18px 20px; }

  .gnpd .gnpd-figure { font-size: 24px; }

  .gnpd-btn {
    height: 50px;
    font-size: 15.5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gnpd * { transition: none; }
  .gnpd-btn:hover { transform: none; }
  .gnpd-countdown__pulse { animation: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · PROGRAM DETAIL
     Service Portal widget · Server script

     Reads one program and publishes it in the shape the page
     needs, including a derived state that decides whether the
     apply button is live.

     GlideRecordSecure only, so a reader sees exactly what the
     read ACLs allow. A program in an internal state is treated
     as not found rather than shown, whatever the ACLs happen to
     permit.

     Field names carry fallbacks because the form has been
     relabelled once already: Program Budget became Program
     Funding, and Summary Statement became Additional
     Information. The first candidate that exists and has a
     value wins.
     ========================================================= */

  var TBL = 'x_enno_gatenow_grant_program';

  var PUBLIC_STATUS = ['accepting_proposals', 'published', 'program_closed'];
  var CLOSING_SOON_DAYS = 7;

  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  /* positive is in the future, negative is past */
  function daysFromNow(value) {
    var g = toGDT(value);
    if (!g) return null;
    try {
      var ms = GlideDateTime.subtract(new GlideDateTime(), g).getNumericValue();
      return Math.round(ms / 86400000);
    } catch (e) { return null; }
  }

  /* fields on this form have been renamed once, so every read
     goes through a candidate list */
  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next candidate */ }
    }
    return '';
  }

  function pickDisplay(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getDisplayValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next candidate */ }
    }
    return '';
  }

  /* currency display values arrive as "$1,000.00" */
  function money(gr, names) {
    var v = pickDisplay(gr, names);
    if (!v) return '';
    v = ('' + v).replace(/\.00$/, '');
    return v === '$0' || v === '0' ? '' : v;
  }

  /* the long fields are plain text areas on the form, so any
     markup is stripped and the line breaks are kept by the
     stylesheet rather than converted to elements */
  function text(gr, names) {
    var raw = pick(gr, names);
    if (!raw) return '';
    return ('' + raw)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }


  /* ---------- copy ---------- */
  data.labels = {
    back        : opt('label_back', gs.getMessage('All programs')),
    apply       : opt('label_apply', gs.getMessage('Start application')),
    applyClosed : opt('label_apply_closed', gs.getMessage('Applications closed')),
    applySoon   : opt('label_apply_soon', gs.getMessage('Not open yet')),
    about       : opt('label_about', gs.getMessage('About this program')),
    eligibility : opt('label_eligibility', gs.getMessage('Who can apply')),
    terms       : opt('label_terms', gs.getMessage('Terms and conditions')),
    more        : opt('label_more', gs.getMessage('Additional information')),
    notice      : opt('label_notice', gs.getMessage('Announcement')),
    funding     : opt('label_funding', gs.getMessage('Funding')),
    dates       : opt('label_dates', gs.getMessage('Key dates')),
    admin       : opt('label_admin', gs.getMessage('Administration')),
    range       : opt('label_range', gs.getMessage('Award range')),
    pot         : opt('label_pot', gs.getMessage('Total programme funding')),
    awardType   : opt('label_award_type', gs.getMessage('Award type')),
    disburse    : opt('label_disburse', gs.getMessage('Paid by')),
    schedule    : opt('label_schedule', gs.getMessage('Schedule')),
    opens       : opt('label_opens', gs.getMessage('Applications open')),
    closes      : opt('label_closes', gs.getMessage('Applications close')),
    starts      : opt('label_starts', gs.getMessage('Programme starts')),
    ends        : opt('label_ends', gs.getMessage('Programme ends')),
    manager     : opt('label_manager', gs.getMessage('Program manager')),
    opportunity : opt('label_opportunity', gs.getMessage('Funding opportunity number')),
    listing     : opt('label_listing', gs.getMessage('Assistance listing number')),
    reference   : opt('label_reference', gs.getMessage('Reference'))
  };

  data.applyNote = opt('apply_note', gs.getMessage(
    'You can save a draft and come back to it. Nothing is submitted until you say so.'));

  data.missingTitle = opt('missing_title', gs.getMessage('Program not available'));
  data.missingText  = opt('missing_text', gs.getMessage(
    'This program either does not exist or is not open to applicants. It may ' +
    'have been withdrawn since the link was shared.'));

  /* ADJUST if your listing page id differs */
  data.backUrl = opt('back_url', '?id=opportunities');

  /* the intake page the apply button hands off to */
  data.intakePage  = opt('intake_page', 'applicant_intake');
  data.intakeParam = opt('intake_param', 'sys_id');


  /* ---------- the record ---------- */
  data.found = false;

  var sysId = $sp.getParameter('sys_id') || opt('sys_id', '');

  if (sysId) {
    try {

      var gr = new GlideRecordSecure(TBL);

      if (gr.get(sysId)) {

        var statusValue = lower(gr.getValue('status'));

        /* Draft, Pending Approval and Rejected are internal. A
           direct link to one is treated as not found. */
        if (PUBLIC_STATUS.indexOf(statusValue) !== -1) {

          var closeRaw = gr.getValue('proposal_close_date');
          var openRaw  = gr.getValue('proposal_open_date');

          var daysToClose = daysFromNow(closeRaw);
          var daysToOpen  = daysFromNow(openRaw);

          var accepting = statusValue === 'accepting_proposals';
          var closedTag = statusValue === 'program_closed';

          /* Status alone does not tell an applicant whether they
             can act today, so the state combines status and
             dates. This is what gates the apply button. */
          var state, stateLabel;

          if (closedTag || (daysToClose !== null && daysToClose < 0)) {
            state = 'closed';
            stateLabel = gs.getMessage('Closed');
          } else if (accepting) {
            state = 'open';
            stateLabel = gs.getMessage('Open for applications');
          } else {
            state = 'soon';
            stateLabel = daysToOpen !== null && daysToOpen > 0
              ? gs.getMessage('Opens') + ' ' + fmtDate(openRaw)
              : gs.getMessage('Opening soon');
          }

          var urgent = (state === 'open' && daysToClose !== null && daysToClose <= CLOSING_SOON_DAYS);

          var countdown = '';
          if (state === 'open' && daysToClose !== null) {
            countdown = daysToClose <= 0
              ? gs.getMessage('Closes today')
              : daysToClose + ' ' + (daysToClose === 1 ? gs.getMessage('day left to apply')
                                                       : gs.getMessage('days left to apply'));
          }

          var minAward = money(gr, ['min_award', 'minimum_award']);
          var maxAward = money(gr, ['max_award', 'maximum_award']);

          var range = '';
          if (minAward && maxAward) range = minAward + ' to ' + maxAward;
          else if (maxAward)        range = gs.getMessage('Up to') + ' ' + maxAward;
          else if (minAward)        range = gs.getMessage('From') + ' ' + minAward;

          data.program = {
            sysId      : gr.getUniqueValue(),
            number     : gr.getValue('number'),
            name       : pick(gr, ['program_name', 'short_description', 'number']),
            category   : gr.getDisplayValue('category'),
            state      : state,
            stateLabel : stateLabel,
            urgent     : urgent,
            countdown  : countdown,

            synopsis   : text(gr, ['synopsis', 'program_description']),
            about      : text(gr, ['program_description']),
            eligibility: text(gr, ['eligibility_summary']),
            terms      : text(gr, ['terms_and_conditions']),
            more       : text(gr, ['additional_information', 'summary_statement']),
            notice     : text(gr, ['announcement']),

            range      : range,
            pot        : money(gr, ['program_funding', 'program_budget']),
            awardType  : gr.getDisplayValue('award_type'),
            disburse   : gr.getDisplayValue('disbursement_type'),
            schedule   : gr.getDisplayValue('disbursement_schedule'),

            opens      : fmtDate(openRaw),
            closes     : fmtDate(closeRaw),
            starts     : fmtDate(gr.getValue('start_date')),
            ends       : fmtDate(gr.getValue('end_date')),

            manager    : gr.getDisplayValue('program_manager'),
            opportunity: pick(gr, ['funding_opportunity_number']),
            listing    : pick(gr, ['assistance_listing_number'])
          };

          /* Only the sections with something in them are drawn,
             so a sparsely filled program does not render a page
             of empty headings. */
          data.program.hasAbout       = !!data.program.about && data.program.about !== data.program.synopsis;
          data.program.hasEligibility = !!data.program.eligibility;
          data.program.hasTerms       = !!data.program.terms;
          data.program.hasMore        = !!data.program.more;
          data.program.hasNotice      = !!data.program.notice;

          data.canApply = (state === 'open');

          data.applyUrl = '?id=' + data.intakePage + '&' +
                          data.intakeParam + '=' + gr.getUniqueValue();

          data.found = true;
        }
      }

    } catch (e) {
      gs.error('GateNow program detail: ' + e.message);
    }
  }

})();
